parameters.jsCode:
const ALLOWED_CATEGORIES = new Set(['registration','billing','exams','library','records','it-support','financial-aid','general']);
const ALLOWED_PRIORITIES = new Set(['low','normal','high','urgent']);

function sqlEscape(value) {
  if (value === null || value === undefined) return 'NULL';
  if (typeof value === 'number') return Number.isFinite(value) ? String(value) : 'NULL';
  if (typeof value === 'boolean') return value ? '1' : '0';
  const str = typeof value === 'string' ? value : JSON.stringify(value);
  const escaped = str.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
  return "'" + escaped + "'";
}

const upstream = $('Insert Ticket').first().json;
const norm     = $('Normalize Input').first().json;
const raw      = $input.first().json;

let parsed = null;
let failureReason = null;

if (raw && raw.error) {
  failureReason = `http: ${raw.error.message ?? 'request failed'}`;
} else {
  try {
    const content = raw?.choices?.[0]?.message?.content;
    if (typeof content !== 'string') throw new Error('No message content in response');
    let cleaned = content.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
    const m = cleaned.match(/\{[\s\S]*\}/);  // tolerate text around the JSON
    if (m) cleaned = m[0];
    parsed = JSON.parse(cleaned);
  } catch (err) {
    failureReason = `parse: ${err.message}`;
  }
  if (parsed) {
    if (!ALLOWED_CATEGORIES.has(parsed.category)) { failureReason = `bad category: ${parsed.category}`; parsed = null; }
    else if (!ALLOWED_PRIORITIES.has(parsed.priority)) { failureReason = `bad priority: ${parsed.priority}`; parsed = null; }
    else if (typeof parsed.confidence !== 'number' || parsed.confidence < 0 || parsed.confidence > 1) { failureReason = `bad confidence: ${parsed.confidence}`; parsed = null; }
  }
}

const question = norm.question;
const kb_search_sql = `SELECT
  id,
  title,
  content,
  category,
  MATCH(title, content, keywords)
    AGAINST (${sqlEscape(question)} IN NATURAL LANGUAGE MODE) AS relevance
FROM knowledge_base
WHERE is_active = 1
  AND MATCH(title, content, keywords)
      AGAINST (${sqlEscape(question)} IN NATURAL LANGUAGE MODE)
ORDER BY relevance DESC
LIMIT 5;`;

return [{ json: {
  ticket_id:       upstream.insertId,
  question,
  category:        parsed ? parsed.category   : 'general',
  priority:        parsed ? parsed.priority   : 'normal',
  confidence:      parsed ? parsed.confidence : 0,
  reasoning:       parsed ? parsed.reasoning  : null,
  classified:      Boolean(parsed),
  failure:         failureReason,
  idempotency_key: norm.idempotency_key,
  kb_search_sql,
}}];

// Node 07 "Build Answer Context"
// Search Knowledge Base has alwaysOutputData=true, so when MySQL finds
// zero rows this node still receives one EMPTY item ({}), which is
// filtered out below (no id) -> hits = [] -> sufficient_knowledge=false
// -> the workflow goes to "No KB Match" and the ticket is escalated.
// Tuning knob: minimum MySQL relevance score to auto-answer.
// Set here instead of reading $env, because N8N_BLOCK_ENV_ACCESS_IN_NODE
// is on and blocks $env inside Code nodes. Edit this number to tune it
// against your own knowledge_base content (see BUILD.md).
// InnoDB relevance scores are corpus-relative and low on a small KB:
// clear matches score ~2-10, off-topic questions ~0-1. 4.0 rejected valid
// questions, so the cutoff is 1.5. The answer LLM is instructed to say
// "not covered" if the excerpts don't actually contain the answer.
// InnoDB relevance scores are corpus-relative (tiny on a small KB), so an
// absolute cutoff kept rejecting valid questions. The SQL already requires
// MATCH(...) > 0, so "at least one hit" is the real gate; this is only a floor.
// The answer LLM is instructed to say "not covered" if the excerpts don't
// contain the answer, so a weak hit can't produce an invented answer.
const KB_MATCH_THRESHOLD = 0.05;
// Classification is metadata. Only block if the classifier ran successfully
// AND is clearly unsure; a failed/unparsable classification must not block.
const MIN_CLASS_CONFIDENCE = 0.3;

const cls = $('Validate Classification').first().json;
const raw = $input.all();

const hits     = raw.filter(i => !i.json.error && i.json.id != null).map(i => i.json);
const kbFailed = raw.length > 0 && raw[0].json.error != null;

const scoreOf  = h => { const n = Number(h.relevance); return Number.isFinite(n) ? n : 0; };
const scores   = hits.map(scoreOf);
const topScore = scores.length ? scores[0] : 0;
// score unknown (0) but rows came back -> keep them all
const kept = topScore > 0 ? hits.filter(h => scoreOf(h) >= topScore * 0.15) : hits;

const scoreOk = topScore === 0 || topScore >= KB_MATCH_THRESHOLD;
const confOk  = !cls.classified || Number(cls.confidence) >= MIN_CLASS_CONFIDENCE;

const sufficient_knowledge = !kbFailed && kept.length > 0 && scoreOk && confOk;

let insufficient_reason = null;
if (!sufficient_knowledge) {
  if (kbFailed) insufficient_reason = 'kb_search_failed';
  else if (hits.length === 0) insufficient_reason = 'no_kb_hits';
  else if (!scoreOk) insufficient_reason = 'low_relevance';
  else insufficient_reason = 'low_classification_confidence';
}

const context = kept.map((h, i) => `[${i + 1}] ${h.title} (category: ${h.category})\n${h.content}`).join('\n\n').slice(0, 12000);
const userPrompt = 'Question:\n' + cls.question + '\n\nKnowledge-base excerpts:\n' + (context || '(no relevant excerpts found)');

return [{ json: {
  ticket_id:       cls.ticket_id,
  question:        cls.question,
  category:        cls.category,
  priority:        cls.priority,
  confidence:      cls.confidence,
  classified:      cls.classified,
  failure:         cls.failure,
  kb_failed:       kbFailed,
  matched_kb_ids:  kept.map(h => h.id),
  has_context:     kept.length > 0,
  sufficient_knowledge,
  insufficient_reason,
  top_score:       topScore,
  all_scores:      scores,
  kb_threshold:    KB_MATCH_THRESHOLD,
  context,
  user_prompt:     userPrompt,
  idempotency_key: cls.idempotency_key,
}}];

// Runs only when Build Answer Context found nothing above the
// relevance cutoff (has_context === false). Skips the LLM call
// entirely and writes an explicit, honest 'not in the knowledge
// base' answer instead of letting the model improvise or return
// an empty/blank response.
function sqlEscape(value) {
  if (value === null || value === undefined) return 'NULL';
  if (typeof value === 'number') return Number.isFinite(value) ? String(value) : 'NULL';
  if (typeof value === 'boolean') return value ? '1' : '0';
  const str = typeof value === 'string' ? value : JSON.stringify(value);
  const escaped = str.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
  return "'" + escaped + "'";
}

const ctx = $input.first().json;

const answer = "This question isn't covered in the knowledge base yet. Your request has been logged and a staff member will follow up directly.";
const answered = false;
const status = 'escalated';
const matchedKbJson = JSON.stringify(ctx.matched_kb_ids ?? []);
const errorMessage = `escalated: ${ctx.insufficient_reason ?? 'unknown'} (top_score=${ctx.top_score}, threshold=${ctx.kb_threshold}, confidence=${ctx.confidence})`;

const update_sql = `UPDATE ticket_requests
SET
  category       = ${sqlEscape(ctx.category)},
  priority       = ${sqlEscape(ctx.priority)},
  confidence     = ${sqlEscape(ctx.confidence)},
  status         = ${sqlEscape(status)},
  answer         = ${sqlEscape(answer)},
  matched_kb_ids = ${sqlEscape(matchedKbJson)},
  error_message  = ${sqlEscape(errorMessage)}
WHERE idempotency_key = ${sqlEscape(ctx.idempotency_key)};`;

return [{ json: {
  ...ctx,
  answer,
  answered,
  model_used: null,
  usage: null,
  update_sql,
}}];

function sqlEscape(value) {
  if (value === null || value === undefined) return 'NULL';
  if (typeof value === 'number') return Number.isFinite(value) ? String(value) : 'NULL';
  if (typeof value === 'boolean') return value ? '1' : '0';
  const str = typeof value === 'string' ? value : JSON.stringify(value);
  const escaped = str.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
  return "'" + escaped + "'";
}

const ctx = $('Build Answer Context').first().json;
const raw = $input.first().json;

let answer, answered;
if (raw && raw.error) {
  answer = 'We could not generate an answer for this request. A staff member will follow up.';
  answered = false;
} else {
  const content = raw?.choices?.[0]?.message?.content?.trim();
  answer = content || 'We could not generate an answer for this request. A staff member will follow up.';
  answered = Boolean(content);
}

const status        = answered ? 'answered' : 'failed';
const errorMessage  = ctx.kb_failed ? 'kb search failed' : ctx.failure;
const matchedKbJson = JSON.stringify(ctx.matched_kb_ids ?? []);

const update_sql = `UPDATE ticket_requests
SET
  category       = ${sqlEscape(ctx.category)},
  priority       = ${sqlEscape(ctx.priority)},
  confidence     = ${sqlEscape(ctx.confidence)},
  status         = ${sqlEscape(status)},
  answer         = ${sqlEscape(answer)},
  matched_kb_ids = ${sqlEscape(matchedKbJson)},
  error_message  = ${sqlEscape(errorMessage)}
WHERE idempotency_key = ${sqlEscape(ctx.idempotency_key)};`;

return [{ json: {
  ...ctx,
  answer,
  answered,
  model_used: raw?.model ?? null,
  usage: raw?.usage ?? null,
  update_sql,
}}];

// Both branches converge on Update Ticket -> Compose Reply, but only ONE of
// 'Extract Answer' (KB match -> LLM) or 'No KB Match' (escalated) runs.
// Notes:
//  - Referencing a node that didn't run throws, so each lookup is guarded.
//  - Do NOT read from 'Check KB Match' here: it is an IF node with two
//    outputs and $('Check KB Match').first() returns undefined when the
//    branch can't be resolved. 'Build Answer Context' has one output and
//    carries the same fields.
function getJson(name) {
  try {
    const item = $(name).first();
    return item ? item.json : null;
  } catch (e) {
    return null;                       // node didn't run in this execution
  }
}

const n   = getJson('Normalize Input') ?? {};
const ctx = getJson('Build Answer Context') ?? {};

const d = ctx.sufficient_knowledge
  ? (getJson('Extract Answer') ?? getJson('No KB Match'))
  : (getJson('No KB Match')    ?? getJson('Extract Answer'));

if (!d) throw new Error('Compose Reply: neither Extract Answer nor No KB Match produced output');

const ticketCode = 'REQ-' + String(n.idempotency_key || '').slice(0, 8).toUpperCase();
const status = d.answered ? 'auto_resolved' : 'waiting_for_human';

return [{ json: {
  ticket_code: ticketCode,
  ticket_id:   ticketCode,
  category:    d.category,
  priority:    d.priority,
  status,
  answer:      d.answer,
  sources:     d.matched_kb_ids ?? [],
  // debug: remove once tuned
  debug: {
    reason:     ctx.insufficient_reason,
    top_score:  ctx.top_score,
    all_scores: ctx.all_scores,
    threshold:  ctx.kb_threshold,
    confidence: ctx.confidence,
    classified: ctx.classified,
    failure:    ctx.failure,
  },
}}];
